using System;
using System.Diagnostics;
using System.Text.Json;
using Amazon.Lambda.Core;
using FibBindings;

[assembly: LambdaSerializer(typeof(Amazon.Lambda.Serialization.SystemTextJson.DefaultLambdaJsonSerializer))]

public class Function
{
    // Binding auto-generated by csbindgen from src/lib.rs — see NativeMethods.g.cs
    // No manual [DllImport] needed!

    public object Handler(JsonElement input, ILambdaContext context)
    {
        var queryParams = input.GetProperty("queryStringParameters");
        long number = long.Parse(queryParams.GetProperty("number").GetString() ?? "35");

        context.Logger.LogLine($"Starting fib({number})");

        var sw = Stopwatch.StartNew();
        var result = NativeMethods.fib(number);
        sw.Stop();
        var elapsedMs = sw.Elapsed.TotalMilliseconds;

        context.Logger.LogLine("Done");

        return new
        {
            statusCode = 200,
            body = JsonSerializer.Serialize(new
            {
                result = result,
                elapsed_ms = Math.Round(elapsedMs, 2),
                engine = "csharp+rust-csbindgen"
            })
        };
    }
}
